## Exercices Algorithmiques

### algo_facile_1 — validerParentheses(s)

```javascript
function validerParentheses(s) {
    let balance = 0;
    for (const char of s) {
        if (char === '(') balance++;
        else if (char === ')') balance--;
        if (balance < 0) return false;
    }
    return balance === 0;
}
```

### algo_facile_2 — fibonacci(n)

```javascript
function fibonacci(n) {
    if (n < 0) return undefined;
    if (n === 0) return 0;
    if (n === 1) return 1;

    let a = 0, b = 1;
    for (let i = 2; i <= n; i++) {
        const temp = a + b;
        a = b;
        b = temp;
    }
    return b;
}
```

### algo_moyen_1 — motsUniques(s)

```javascript
function motsUniques(s) {
    if (!s || typeof s !== 'string') return 0;
    // Sépare les mots par des espaces et compte les distincts
    const words = s.trim().split(/\s+/);
    const unique = new Set(words);
    return unique.size;
}
```

### algo_difficile_1 — aplatirTableau(tab)

```javascript
function aplatirTableau(tab) {
    if (!Array.isArray(tab)) return [];
    const result = [];
    for (const item of tab) {
        if (Array.isArray(item)) {
            result.push(...item);
        } else {
            result.push(item);
        }
    }
    return result;
}
```

### algo_defi — rotationDroite(tab, k)

```javascript
function rotationDroite(tab, k) {
    if (!Array.isArray(tab) || k === undefined) return [];
    const n = tab.length;
    if (n === 0) return [];

    // Normalise k pour éviter les rotations multiples inutiles
    k = ((k % n) + n) % n;

    // Rotation à droite de k positions
    const result = [...tab];
    for (let i = 0; i < k; i++) {
        const last = result.pop();
        result.unshift(last);
    }
    return result;
}
```

